export default function ({ body, previous }) {
  if (!Array.isArray(body)) throw Error("Invalid Hacker News top stories");
  const ids = body.slice(0, 30);
  if (ids.some((x) => !Number.isSafeInteger(x) || x <= 0)) throw Error("Invalid story ID");
  const index = (previous?.index ?? -1) + 1,
    id = ids[index];
  return {
    state: { index },
    more: id !== undefined,
    url: id
      ? `https://hacker-news.firebaseio.com/v0/item/${id}.json`
      : "https://hacker-news.firebaseio.com/",
    id: String(id ?? ""),
  };
}

