export default function ({ body, id }) {
  if (!body || String(body.id) !== id) throw Error("Story response mismatched");
  let good = false;
  try {
    const u = new URL(body.url);
    good = u.protocol === "https:" && u.hostname.toLowerCase() === "github.com";
  } catch {}
  const title = typeof body.title === "string" ? body.title : "";
  return {
    id,
    match: good && !!title,
    title,
    url: good ? body.url : "",
    formula: `{Post} = '${id}'`,
  };
}

