export default function ({ storyId, title, url, page, result }) {
  if (!page?.success || !page.data?.markdown) throw Error("GitHub page unavailable");
  const { twitter, linkedin } = result || {};
  if (
    typeof twitter !== "string" ||
    !twitter.includes(url) ||
    [...twitter].length > 280 ||
    typeof linkedin !== "string" ||
    !linkedin.includes(url) ||
    !linkedin.trim()
  )
    throw Error("Invalid social posts");
  return {
    records: [
      { fields: { Post: storyId, Title: title, Url: url, Tweet: twitter, LinkedIn: linkedin } },
    ],
    notice: `Proposed X post:\n${twitter}\n\nProposed LinkedIn post:\n${linkedin}`,
    twitter,
    linkedin,
  };
}

