export default async function ({ id, posted }, ctx) {
  const key = "hn-social:" + id + ":record";
  if (posted) return { key, skip: true };
  const s = await ctx.state.get(key);
  if (s?.status === "pending") throw Error("Inspect record before retry");
  if (s?.status === "done") return { key, skip: true };
  await ctx.state.set(key, { status: "pending" });
  return { key, skip: false };
}

