export default function ({ existing, created }) {
  const r = created?.[0] ?? existing?.[0],
    f = r?.fields;
  if (
    !r?.id ||
    !f ||
    typeof f.Tweet !== "string" ||
    !f.Tweet ||
    typeof f.LinkedIn !== "string" ||
    !f.LinkedIn
  )
    throw Error("Existing story record lacks saved posts");
  return {
    id: r.id,
    twitter: f.Tweet,
    linkedin: f.LinkedIn,
    notice: `Proposed X post:\n${f.Tweet}\n\nProposed LinkedIn post:\n${f.LinkedIn}`,
    xDone: f.TDone === true,
    liDone: f.LDone === true,
  };
}

